insert into public.content (id,slug,kind,title,excerpt,category,body_html,status,year,place,company,reflection,article_slug) values
('08703a7d-c933-5fcc-a83c-60fe02aec3d9','2008','moment','Antes do primeiro emprego.','Estudos em desenvolvimento web','Vida','<p>Comecei a estudar desenvolvimento web em 2008. Virava a noite entre padrões web, HTML, CSS e JavaScript. Precisava trabalhar, mas as oportunidades por ali eram poucas.</p><p>Minha vida estava naquela cidade: os amigos, a bicicleta, o hardcore. Conseguir o primeiro emprego acabaria me levando para longe de tudo isso.</p>','published','2008','Ipatinga · Minas Gerais','O começo','A oportunidade veio de Uberlândia.','dez-anos-atras-eu-morava-em-ipatinga'),
('f2e9249a-6585-5f2b-abea-e778fd044748','2009','moment','Do PSD ao navegador.','Junho de 2009 — setembro de 2010','Vida','<p>Na Webroom, transformava layouts em PSD em páginas HTML e CSS. Desenvolvia sites compatíveis com diferentes navegadores e aplicava técnicas básicas de SEO.</p><p>Também fazia revisões e validações das entregas. Foi meu primeiro trabalho com desenvolvimento de interfaces, em Uberlândia.</p>','published','2009','Uberlândia · Minas Gerais','Webroom Soluções Interativas',NULL,NULL),
('fbb61eea-4a46-5729-a243-2ffa5883c895','2010','moment','Programação de interfaces.','Setembro de 2010 — abril de 2011','Vida','<p>Na Commquest, convertia layouts em interfaces web, com atenção a desempenho e compatibilidade entre navegadores.</p><p>Participava dos testes, da depuração e da manutenção dos sites, aplicando melhorias de acessibilidade e usabilidade.</p>','published','2010','Belo Horizonte · Minas Gerais','Commquest Comunicação',NULL,NULL),
('63e4a774-cffc-5184-aca6-4aa26afaa65f','2011','moment','Interfaces web e WordPress.','Abril de 2011 — agosto de 2012','Vida','<p>Na Lápis Raro, desenvolvi interfaces com HTML5, CSS e JavaScript, funcionalidades com jQuery e temas personalizados para WordPress.</p><p>Trabalhava com designers na implementação dos layouts e na adaptação das páginas a diferentes telas.</p>','published','2011','Belo Horizonte · Minas Gerais','Lápis Raro',NULL,NULL),
('7bf63ec6-572a-5e4a-a856-214afca07461','2012','moment','Sites, componentes e equipe criativa.','Agosto de 2012 — fevereiro de 2015','Vida','<p>Na 3bits, desenvolvi sites para marcas como Coca-Cola Brasil e BDMG, com jQuery e WordPress.</p><p>Usava Sass e Git, implementava componentes personalizados e cuidava da responsividade e compatibilidade entre navegadores. Trabalhava com a equipe criativa para transformar layouts em interfaces.</p>','published','2012','Belo Horizonte · Minas Gerais','3bits Estúdio Criativo',NULL,NULL),
('04bd0432-8a57-5bdd-a2e0-9a89c68c80be','2015','moment','Sites e aplicações por conta própria.','Fevereiro de 2015 — março de 2023','Vida','<p>Como freelancer, desenvolvi sites e sistemas com Vue, Nuxt, React e WordPress. O trabalho incluía integração com APIs, interfaces responsivas, SEO, acessibilidade e gestão das entregas.</p><p>Nesse período também fui para Angueretá. Dividia a rotina entre o computador e a roça: leite, queijo, galinhas, capina e cavalos.</p>','published','2015','Trabalho remoto · Angueretá','Freelancer','Eu não nasci sertanejo, fui forjado.','um-ano-e-meio-de-roca'),
('03dfabb9-3997-5f78-a84b-9699e2433c04','2022','moment','Sustentação de aplicações web e mobile.','Maio de 2022 — março de 2023','Vida','<p>Na Plural Systems, trabalhei na sustentação e manutenção de sistemas em AngularJS, React e React Native.</p><p>Desenvolvi soluções reutilizáveis para aplicações existentes, integrei serviços Azure e corrigi bugs críticos. A rotina incluía Scrum, definição de sprints, revisão de código e testes.</p>','published','2022','Trabalho remoto','Plural Systems',NULL,'na-linha-de-frente-retomei-minha-profissao'),
('43ae4a88-33bd-5e7b-acf7-c02398b096c5','2023','moment','Vue e TypeScript em produto.','Dezembro de 2023 — maio de 2024','Vida','<p>Desenvolvi o front-end da plataforma da Evavip com Vue.js e TypeScript, construindo funcionalidades interativas e responsivas.</p><p>Trabalhei na melhoria contínua do desempenho da aplicação em colaboração com as demais áreas do produto.</p>','published','2023','Trabalho remoto','Evavip.com',NULL,'por-um-2023-mais-textual'),
('e992bdec-efcc-598a-a2d1-63f1af27549e','2025','moment','Evolução de uma plataforma Angular.','Março de 2025 — presente','Vida','<p>Na Trade Arena, desenvolvo o front-end de uma plataforma de treinamento para traders, com operações simuladas e dados de mercado em tempo real. Trabalho com Angular e TypeScript em uma aplicação de grande porte.</p><p>Atuo na migração incremental entre versões do Angular, na organização de estado e fluxos assíncronos com RxJS e na extração de lógica compartilhada para serviços, facades e ViewModels.</p><p>Desenvolvo dashboards, rankings, chats e fluxos financeiros, com integração a APIs REST e WebSocket. Também trabalho na padronização de componentes e SCSS, em acessibilidade, responsividade, performance e testes unitários.</p><p>Crio diretrizes para que o desenvolvimento assistido por IA siga os padrões do projeto.</p>','published','2025','Belo Horizonte e região · trabalho híbrido','Trade Arena',NULL,'do-caos-flash-ao-tedio-flat'),
('6d480f22-20dc-547e-a7ee-7bd96752bb30','agora','moment','A vida com Acauã.','Um momento de realização','Vida','<p>Estou com meu filho Acauã. A paternidade marca este momento de realização.</p><p>Continuo trabalhando com front-end e acompanhando as mudanças da profissão. O futuro traz perguntas; o trabalho de hoje é concreto.</p>','published','Agora','Presença & futuro','O presente',NULL,NULL),
('68ff3f83-95f5-5f16-ac3b-2de2781b8cca','2011-hollo','moment','Front-end na hollo interact.','2011 — 2012','Vida','<p>Atuei como Front End Developer na hollo interact, em Belo Horizonte. Esta experiência aparece no meu histórico profissional do Facebook.</p>','published','2011–2012','Belo Horizonte · Minas Gerais','hollo interact',NULL,NULL)
